from lib import *
S = SS('v1')
steps = [
    step("先看固定超时和传播截止时间的差别。client → A → B → C,client 总预算 1000 ms,C 有 30% 的请求要 1500 ms(其余 100 ms),200 个请求、20 个并发,按请求编号预先数出来有 74 个会让 C 慢。每一跳各自固定 1000 ms 超时、互不知情:126 个请求在 1 s 内拿到结果,70 个 client 超时,4 个拿到 504;C 把 200 个请求的活全部干完,花在干活上的总时间 123.6 s,其中 74 次干完时 client 早已放弃。每一跳传播剩余预算(C 每 10 ms 看一眼剩余预算,没了就停):同样是 126 个拿到结果,但另外 74 个都很快拿到 504,没有 client 超时;C 只把 126 个活干完,总时间 73.9 s,干完时 client 已放弃的次数是 0。1500 ms 的活在 1000 ms 的预算里本来就做不完,两种策略的成功数一样,差别在于下游有没有替早已离开的 client 白干。", t=tl(S(1)), mark=lidx(S(1), '每一跳固定 1000 ms 超时'), done=lidx(S(1), '传播剩余预算'), b=bars([['固定超时:C 干活总时间 s', 123.6, '123.6'], ['传播预算:C 干活总时间 s', 73.9, '73.9'], ['固定超时:干完时 client 已放弃', 74, '74 次'], ['传播预算:干完时 client 已放弃', 0, '0 次']], 123.6, mark=[0, 2], done=[1, 3]), kv=KV([['成功数', '两种都是 126 / 200'], ['固定超时', '70 个 client 超时,C 白干 74 次'], ['传播预算', '74 个很快拿到 504,C 干活时间少 50 s']], ['传播预算'])),
    step("再看重试吃掉预算。C 一直很慢(1500 ms),B 最多对 C 试 3 次、每次 500 ms 超时,client 总预算 1000 ms,40 个请求、10 个并发。固定每次 500 ms:client 全部 40 个超时、什么也没等到,延迟中位数 1002 ms;C 一共收到 120 次调用,其中 40 次是 client 放弃之后才发来的(第 3 次尝试在 1000 ms 才开始)。每次不超过剩余预算(剩余不到 50 ms 就不再试):40 个请求都在 1 s 内拿到 B 的 504,延迟中位数 985 ms;C 只收到 80 次调用,没有一次是 client 放弃之后才发来的。B 带着重试时,总耗时 = 次数 × 每次的超时,不看剩余预算就会超过上游的预算。", t=tl(S(2)), mark=lidx(S(2), '固定:每次 500 ms'), done=lidx(S(2), '每次 ≤ 剩余预算'), b=bars([['固定:C 收到的调用', 120, '120'], ['预算:C 收到的调用', 80, '80'], ['固定:client 放弃后才发来的', 40, '40'], ['预算:client 放弃后才发来的', 0, '0']], 120, mark=[0, 2], done=[1, 3]), kv=KV([['固定 500 ms × 3', '40 / 40 个 client 超时'], ['每次 ≤ 剩余预算', '40 / 40 个在 1 s 内得到 504'], ['对 C 的调用', '120 次对 80 次']], ['每次 ≤ 剩余预算'])),
    step("预算怎么分。三个串行的下游 S1、S2、S3,正常 100 ms、各有 5% 的请求在这一跳要 600 ms,总预算 1000 ms,400 个请求、40 个并发。按随机数事先数出来:至少一跳慢的请求 50 个,至少两跳慢的请求 7 个。预算平分、每跳 333 ms 超时:350 / 400 成功(87.5%),成功请求延迟中位数 316 ms、p99 337 ms,有慢一跳的请求必败。整条链共用剩余预算:393 / 400 成功(98.2%),中位数 315 ms、p99 823 ms;只有两跳以上慢(600 + 600 > 1000)才失败。共用预算把前面省下来的时间留给后面慢的那一跳,代价是成功请求的 p99 更高。", t=tl(S(3)), mark=lidx(S(3), '预算平分'), done=lidx(S(3), '共用剩余预算', '按随机数事先数出来'), b=bars([['平分:成功数', 350, '350 / 400'], ['共用预算:成功数', 393, '393 / 400'], ['平分:成功请求 p99 ms', 337, '337'], ['共用预算:成功请求 p99 ms', 823, '823']], 823, cur=[0, 2], done=[1], mark=[3]), kv=KV([['平分 333 ms', '87.5%,慢一跳就必败'], ['共用预算', '98.2%,两跳慢才败'], ['代价', '成功请求 p99 337 → 823 ms']], ['共用预算'])),
    step("最后看排队。一个服务只有一个 worker、每个请求 20 ms(容量 50/s),到达率 80/s 持续 5 秒共 400 个请求,截止时间 400 ms。来者不拒:只有 34 个在 400 ms 内成功,366 个 client 超时(或晚于 400 ms);worker 实际处理了 313 个,其中 279 个处理完时已超过截止时刻,白干。出队时发现剩余时间不够 20 ms 就直接丢掉:162 个成功,62 个超时,176 个收到 504;worker 只处理 224 个(54 个超过截止时刻),直接丢掉 176 个。排队越长、排到的请求越是没人在等,检查截止时间能把 worker 的时间花在还有人等的请求上;但仍有 54 个在检查通过后(要再 20 ms)才完成而过期。", t=tl(S(4)), mark=lidx(S(4), '来者不拒      |'), done=lidx(S(4), '出队时丢掉已过期的'), b=bars([['来者不拒:成功', 34, '34'], ['丢弃过期:成功', 162, '162'], ['来者不拒:处理完已过期', 279, '279'], ['丢弃过期:处理完已过期', 54, '54']], 313, mark=[0, 2], done=[1, 3]), kv=KV([['来者不拒', '34 / 400 成功,279 次白干'], ['出队检查截止时间', '162 / 400 成功,176 个直接丢掉'], ['容量', '50/s,到达 80/s']], ['出队检查截止时间'])),
]
A = mkartv('v1', 1, '微服务,弹性,超时,截止时间,排队,真实验证,动画演示',
    '实测超时预算:每一跳固定 1000 ms 时 C 为 74 个已放弃的请求白干;传播剩余预算后 C 干活时间从 123.6 s 降到 73.9 s;重试 3 次会吃掉预算(120 次对 80 次调用);共用剩余预算的成功率 98.2% 对平分的 87.5%;排队超过截止时间就丢,成功数 34 → 162。',
    '一条调用链上,每一跳的超时该设多少?固定超时、传播剩余预算、重试和排队分别会发生什么?这篇用本机起的几个小 HTTP 服务,把“预算”在多跳之间怎么被吃掉、被浪费量出来。',
    [('123.6 s → 73.9 s', 'C 花在干活上的总时间:每一跳固定 1000 ms 超时 对 传播剩余预算(成功数都是 126 / 200)'), ('120 → 80', '重试 3 次、每次 500 ms 对 每次不超过剩余预算时,C 收到的调用数(前者 40 次是 client 放弃之后才发来的)'), ('34 → 162', '到达率 80/s、容量 50/s 时 400 ms 内成功的请求数:来者不拒 对 出队时丢掉已过期的')],
    [('固定超时 vs 传播截止时间', '<p>两种策略的成功数一样,差别在下游:固定超时的下游不知道 client 已经走了,会把活干完;传播剩余预算后下游可以提前停下。</p>'),
     ('重试怎么吃掉预算', '<p>总耗时 = 次数 × 每次超时。不看剩余预算,最后一次尝试会在 client 放弃之后才发出。</p>'),
     ('预算怎么分', '<p>平分预算让任何一跳变慢都必败;共用剩余预算把前面省下的时间留给后面,代价是成功请求的 p99 更高。</p>'),
     ('排队的请求要看截止时间', '<p>队列越长,排到的请求越是没人在等。出队时检查剩余时间,把容量留给还有人等的请求。</p>')],
    steps,
    [ENV_V + '。本篇的服务是 Python 3.14 http.server(线程化)在本进程里起的,“耗时”用 sleep 模拟,慢请求由请求编号的 crc32 决定,所以两种策略面对完全相同的慢请求;第四节为了让“处理完时是否已超过截止时刻”算得准,把绝对截止时刻放进 X-Deadline 头,client 和服务在同一台机器上所以时钟一致,真实系统里传的是剩余时间(如 gRPC 的 grpc-timeout 头)',
     '没有验证:真实网络的延迟与抖动(都在环回上);跨机器时钟偏差对绝对截止时刻的影响;下游干活时能否被取消取决于语言和库(这里是 C 每 10 ms 自己查一次剩余预算);Python 的 GIL 与线程调度对毫秒级计时的影响(同一台机器上起了几百个线程);出队检查通过后仍有 54 个在 20 ms 的处理里过期,没有做“按预计处理时间提前丢”的进一步调参'],
    '超时预算与截止时间')
